import React, { useState, useEffect } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Table from '../../../components/ui/Table/Table';
import InputField from '../../../components/ui/InputField/InputField';
import Modal from '../../../components/ui/Modal/Modal';
import Button from '../../../components/ui/Button/Button';
import api from '../../../api/api';
import styles from './ListOngsPage.module.css'; // Importa o CSS para os modais

const ListOngsPage = () => {
  const [ongs, setOngs] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOng, setSelectedOng] = useState(null);
  const [isViewModalOpen, setViewModalOpen] = useState(false);
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);

  const headers = [
    { key: 'id', label: 'ID' },
    { key: 'fantasy_name', label: 'Nome Fantasia' },
    { key: 'cnpj', label: 'CNPJ' },
    { key: 'responsible_name', label: 'Responsável' },
    { key: 'contact_email', label: 'Email' },
  ];

  const fetchOngs = async () => {
    try {
      const response = await api.get('/ongs');
      setOngs(response.data);
    } catch (error) {
      console.error("Erro ao buscar ONGs:", error);
    }
  };

  useEffect(() => {
    fetchOngs();
  }, []);

  const handleView = (ong) => {
    setSelectedOng(ong);
    setViewModalOpen(true);
  };

  const handleDelete = (ong) => {
    setSelectedOng(ong);
    setDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    try {
      await api.delete(`/ongs/${selectedOng.id}`);
      setDeleteModalOpen(false);
      fetchOngs(); // Atualiza a lista após a exclusão
    } catch (error) {
      console.error("Erro ao excluir ONG:", error);
      alert("Ocorreu um erro ao excluir a ONG.");
    }
  };

  const filteredOngs = ongs.filter(ong =>
    ong.fantasy_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ong.responsible_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ong.contact_email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <ContentWrapper title="Listar ONGs">
      <div style={{ marginBottom: '1.5rem', maxWidth: '400px' }}>
        <InputField
          label="Pesquisar por nome, responsável ou email"
          name="search"
          placeholder="Digite para pesquisar..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>
      <Table 
        headers={headers} 
        data={filteredOngs} 
        onView={handleView}
        onDelete={handleDelete}
      />

      {/* Modal de Visualização */}
      <Modal 
        isOpen={isViewModalOpen} 
        onClose={() => setViewModalOpen(false)} 
        title="Detalhes da ONG"
      >
        {selectedOng && (
          <div className={styles.modalContent}>
            <p><strong>ID:</strong> {selectedOng.id}</p>
            <p><strong>Nome Fantasia:</strong> {selectedOng.fantasy_name}</p>
            <p><strong>CNPJ:</strong> {selectedOng.cnpj}</p>
            <p><strong>Responsável:</strong> {selectedOng.responsible_name}</p>
            <p><strong>Email de Contato:</strong> {selectedOng.contact_email}</p>
            <p><strong>Telefone:</strong> {selectedOng.phone}</p>
            <div className={styles.modalActions}>
              <Button onClick={() => alert('Navegar para editar perfil da ONG')}>Editar Perfil</Button>
            </div>
          </div>
        )}
      </Modal>

      {/* Modal de Exclusão */}
      <Modal 
        isOpen={isDeleteModalOpen} 
        onClose={() => setDeleteModalOpen(false)} 
        title="Confirmar Exclusão"
      >
        {selectedOng && (
          <div className={styles.modalContent}>
            <p>Tem a certeza de que deseja excluir a ONG <strong>{selectedOng.fantasy_name}</strong>?</p>
            <p>Esta ação não pode ser desfeita.</p>
            <div className={styles.modalActions}>
              <Button variant="secondary" onClick={() => setDeleteModalOpen(false)}>Cancelar</Button>
              <Button variant="danger" onClick={confirmDelete}>Excluir</Button>
            </div>
          </div>
        )}
      </Modal>
    </ContentWrapper>
  );
};

export default ListOngsPage;
